// Press FLASH (D3) to read the light level on A0
const int BUTTON = D3;   // FLASH button: GPIO0, LOW while pressed
const int LIGHT = A0;    // LDR divider on the only analog pin

bool wasPressed = false;

void setup() {
  Serial.begin(115200);
  pinMode(BUTTON, INPUT);            // R1 on the board is the pull-up
  pinMode(LED_BUILTIN, OUTPUT);
  digitalWrite(LED_BUILTIN, HIGH);   // HIGH switches the blue LED off
  Serial.println("ready: press FLASH");
}

void loop() {
  bool pressed = digitalRead(BUTTON) == LOW;
  digitalWrite(LED_BUILTIN, pressed ? LOW : HIGH);
  if (pressed && !wasPressed) {
    int raw = analogRead(LIGHT);
    float volts = raw * 3.2 / 1023.0;  // the board's divider makes 3.2 V read as 1023
    Serial.print("A0 raw=");
    Serial.print(raw);
    Serial.print(" volts=");
    Serial.println(volts, 2);
  }
  wasPressed = pressed;
  delay({{p:debounce}});   // a short pause also rides over contact bounce
}

